package nuts

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
)

// DefaultJoinTimeout bounds how long [ShutdownGroup.Shutdown] waits for
// background loops to return before draining the connections anyway.
const DefaultJoinTimeout = 10 * time.Second

// ShutdownGroup coordinates graceful shutdown of a set of background
// pull-consumer loops and the NATS connections they use. It encodes the
// ordering that prevents rollout noise (COR-923): on Shutdown it cancels the
// loops' context, waits for them to return, and only THEN drains the
// connections — so a Drain never races an in-flight Fetch.
//
// Typical use in a service main:
//
//	g := nuts.NewShutdownGroup(ctx)
//	nc, _ := nuts.Connect(g.Context(), url, nuts.WithName("worker"))
//	g.AddConn("worker", nc)
//	g.Go(func(ctx context.Context) { consumer.Run(ctx) }) // returns on ctx.Done
//	<-g.Context().Done() // SIGTERM/SIGINT, panic, or premature loop return
//	if err := g.Shutdown(); err != nil { return err }
type ShutdownGroup struct {
	ctx          context.Context
	cancel       context.CancelCauseFunc
	logger       *slog.Logger
	joinTimeout  time.Duration
	drainTimeout time.Duration

	wg     sync.WaitGroup
	mu     sync.Mutex
	conns  []groupConn
	closed bool  // set under mu once shutdown starts; gates Go registration
	err    error // first unexpected loop or shutdown failure
	once   sync.Once
}

type groupConn struct {
	name string
	nc   *nats.Conn
}

// GroupOption configures a [ShutdownGroup].
type GroupOption func(*ShutdownGroup)

// WithGroupLogger sets the logger for shutdown diagnostics. Defaults to
// [slog.Default].
func WithGroupLogger(l *slog.Logger) GroupOption { return func(g *ShutdownGroup) { g.logger = l } }

// WithJoinTimeout overrides [DefaultJoinTimeout] — the bound on waiting for
// background loops to return.
func WithJoinTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.joinTimeout = d }
}

// WithGroupDrainTimeout overrides the fallback subscription-drain budget
// ([DefaultDrainTimeout]) used when draining a registered connection that does
// not carry its own nats.DrainTimeout. A connection created with
// [WithDrainTimeout] is drained on its own budget regardless; the total
// time-to-CLOSED backstop adds publish-flush headroom on top (see [Drain]).
func WithGroupDrainTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.drainTimeout = d }
}

// NewShutdownGroup returns a group whose context derives from parent and is
// cancelled by [ShutdownGroup.Shutdown].
func NewShutdownGroup(parent context.Context, opts ...GroupOption) *ShutdownGroup {
	ctx, cancel := context.WithCancelCause(parent)
	g := &ShutdownGroup{
		ctx:          ctx,
		cancel:       cancel,
		logger:       slog.Default(),
		joinTimeout:  DefaultJoinTimeout,
		drainTimeout: DefaultDrainTimeout,
	}
	for _, o := range opts {
		o(g)
	}
	if g.logger == nil {
		g.logger = slog.Default()
	}
	return g
}

// Context returns the group's context, cancelled when Shutdown is called or a
// tracked loop fails. Pass it to every background loop and to [Connect] so the
// loops exit before their connections are drained.
func (g *ShutdownGroup) Context() context.Context { return g.ctx }

// Err returns the first unexpected loop or shutdown failure, or nil while the
// group is healthy and after a clean shutdown. It is safe to call from a
// readiness check while the group is running.
func (g *ShutdownGroup) Err() error {
	g.mu.Lock()
	defer g.mu.Unlock()
	return g.err
}

// Go runs fn as a tracked background loop. fn MUST return when its context is
// cancelled; Shutdown blocks (bounded by the join timeout) until it does.
//
// A panic in fn is recovered so Shutdown can still join the other loops and
// drain connections, but it remains fatal to the group: the panic is recorded,
// logged with a stack, and cancels the group context. A return while the group
// context is still live is handled the same way. The owning process can observe
// the failure through [ShutdownGroup.Err] or [ShutdownGroup.Shutdown].
//
// Registering a loop after Shutdown has begun is a no-op: the loop would not be
// joined before the connections drain, so it is refused and logged rather than
// started. Go is safe to call concurrently with Shutdown.
func (g *ShutdownGroup) Go(fn func(ctx context.Context)) {
	// Add under the same lock that Shutdown takes before it calls wg.Wait, so a
	// concurrent Go/Shutdown can never race Add against Wait (which panics), and
	// a loop registered after shutdown starts is refused rather than left
	// unjoined.
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.Go called after shutdown; loop not started")
		return
	}
	g.wg.Add(1)
	g.mu.Unlock()

	go func() {
		defer g.wg.Done()
		defer func() {
			if r := recover(); r != nil {
				err := fmt.Errorf("nuts: background loop panicked: %v", r)
				g.logger.ErrorContext(g.ctx, "nuts: background loop panicked",
					slog.Any("panic", r), slog.String("stack", string(debug.Stack())))
				g.recordError(err, true)
				return
			}
			if g.recordPrematureReturn() {
				g.logger.ErrorContext(g.ctx, "nuts: background loop returned before shutdown")
			}
		}()
		fn(g.ctx)
	}()
}

// recordPrematureReturn atomically distinguishes a real dead subsystem from a
// loop returning concurrently with Shutdown. Shutdown marks closed under the
// same lock before cancelling, so a normal teardown cannot be misclassified.
func (g *ShutdownGroup) recordPrematureReturn() bool {
	err := errors.New("nuts: background loop returned before shutdown")
	g.mu.Lock()
	if g.closed || g.ctx.Err() != nil {
		g.mu.Unlock()
		return false
	}
	if g.err != nil {
		g.mu.Unlock()
		return false
	}
	g.err = err
	g.mu.Unlock()
	g.cancel(err)
	return true
}

// recordError stores the first group failure. cancelGroup is true for a live
// loop failure, which must stop siblings and the owner; shutdown-time failures
// are returned by Shutdown without re-cancelling an already cancelled group.
func (g *ShutdownGroup) recordError(err error, cancelGroup bool) {
	if err == nil {
		return
	}
	g.mu.Lock()
	recorded := false
	if g.err == nil {
		g.err = err
		recorded = true
	}
	g.mu.Unlock()
	if cancelGroup && recorded {
		g.cancel(err)
	}
}

// AddConn registers a connection to be drained after the loops have joined.
// Draining last — never before the fetch loops stop — is the ordering that
// keeps a Drain/Close from racing an in-flight Fetch (COR-923).
//
// Like [ShutdownGroup.Go], registering after Shutdown has begun is a no-op:
// the drain set is snapshotted when shutdown starts, so a connection added
// afterward (including during the join window) would never be drained. It is
// refused and logged rather than silently dropped — the caller then owns
// tearing it down. Uses the same lock as shutdown's snapshot, so a connection
// is either in the snapshot or explicitly refused, never lost to a race.
func (g *ShutdownGroup) AddConn(name string, nc *nats.Conn) {
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.AddConn called after shutdown; connection not registered for drain",
			slog.String("conn", name))
		return
	}
	g.conns = append(g.conns, groupConn{name: name, nc: nc})
	g.mu.Unlock()
}

// Shutdown cancels the group context, waits (bounded by the join timeout) for
// every Go loop to return, then drains every registered connection. It returns
// the first unexpected loop, join, or drain failure. It is safe to call more
// than once; later calls return the same result.
func (g *ShutdownGroup) Shutdown() error {
	g.once.Do(g.shutdown)
	return g.Err()
}

func (g *ShutdownGroup) shutdown() {
	// Mark closed and snapshot the connections under the lock that Go also
	// takes. After this point no new loop can register (see Go), so the wg.Wait
	// below cannot race a concurrent Add.
	g.mu.Lock()
	g.closed = true
	conns := g.conns
	g.mu.Unlock()

	g.cancel(nil)

	done := make(chan struct{})
	go func() {
		g.wg.Wait()
		close(done)
	}()
	if waitTimedOut(done, g.joinTimeout) {
		g.logger.WarnContext(g.ctx, "nuts: background loops did not stop within join timeout; draining anyway",
			slog.Duration("join_timeout", g.joinTimeout))
		g.recordError(fmt.Errorf("nuts: background loop join timeout after %s", g.joinTimeout), false)
	}

	// Drain the connections concurrently: they are independent, so the group's
	// worst-case shutdown is one drain backstop, not the sum across connections.
	var dwg sync.WaitGroup
	for _, c := range conns {
		dwg.Add(1)
		go func() {
			defer dwg.Done()
			if err := Drain(g.ctx, c.nc, c.name, g.logger, g.drainBackstop(c.nc)); err != nil {
				g.recordError(err, false)
			}
		}()
	}
	dwg.Wait()
}

// waitTimedOut waits for a completion signal and reports whether the timeout
// won. If completion and the timer become ready together, prefer completion:
// work that finished within the observable boundary must not be reported as a
// failure just because select chose the timer pseudo-randomly.
func waitTimedOut[T any](done <-chan T, timeout time.Duration) bool {
	timer := time.NewTimer(timeout)
	defer timer.Stop()

	select {
	case <-done:
		return false
	case <-timer.C:
		select {
		case <-done:
			return false
		default:
			return true
		}
	}
}

// drainBackstop returns the total time-to-CLOSED budget for draining nc. It
// honors the connection's own configured nats.DrainTimeout (set via
// [WithDrainTimeout]) when present, falling back to the group's drain timeout,
// then adds headroom for the publish flush nats.go runs after the
// subscription-drain phase so the backstop does not fire mid-drain (see
// [Drain]).
func (g *ShutdownGroup) drainBackstop(nc *nats.Conn) time.Duration {
	subDrain := g.drainTimeout
	if nc != nil && nc.Opts.DrainTimeout > 0 {
		subDrain = nc.Opts.DrainTimeout
	}
	return subDrain + natsPublishDrainTimeout + time.Second
}
package nuts

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
)

// ErrDrainTimeout is returned when a connection does not reach CLOSED within
// the total drain backstop. The connection is force-closed before return, so
// callers never inherit an ambiguous asynchronous drain.
var ErrDrainTimeout = errors.New("nuts: NATS drain timed out before close")

// transientFetchErrs are the pull-consumer failures a caller recovers from by
// resubscribing: the link to the server went away, or the consumer moved. None
// of them indicate a fault in the caller, and none require operator action —
// the subscribe loop reconnects with backoff and carries on.
//
// The set is drawn from what a rolling restart actually produces. During one
// mirror-pipeline deploy a single pod contributed 57 ErrNoResponders inside 83
// milliseconds as its in-flight fetches failed together; a NATS server upgrade
// produced the same shape via ErrFetchDisconnected and
// ErrConsumerLeadershipChanged. Logged at error level these bursts cross a
// cluster's error-log alert threshold on their own, which trains operators to
// discount the one signal that should mean something (COR-1226 / COR-1228).
//
// nats.ErrConsumerDeleted is deliberately absent. Resubscribing does "recover"
// from it — but by silently recreating the durable with the subscriber's
// default deliver policy and no ack state, which replays the stream's retained
// backlog into downstream systems. A durable that disappears mid-run is
// operator action or a bug, never infrastructure churn, and the log that
// surfaces it is the only evidence of the deletion.
var transientFetchErrs = []error{
	nats.ErrConnectionClosed,
	nats.ErrConnectionDraining,
	nats.ErrDisconnected,
	nats.ErrNoResponders,
	nats.ErrFetchDisconnected,
	nats.ErrConsumerLeadershipChanged,
}

// IsTransientFetchErr reports whether a pull-consumer Fetch or subscribe error
// is a recoverable interruption — a dropped link, a drained connection, a
// consumer that moved or was recreated — rather than a fault. It is
// independent of shutdown: a NATS server rolling underneath a healthy caller
// produces these while ctx is still live.
//
// Callers should log these below error level. The distinction that matters for
// alerting is not "did a fetch fail" but "did it stop recovering", and a single
// interrupted fetch cannot answer that.
//
// nats.ErrTimeout and context.DeadlineExceeded are deliberately absent, and
// the reason is fetch-path-specific: an idle poll reaching MaxWait is the
// steady state of a quiet consumer, and a fetch deadline can be a wedged
// server as easily as a slow one. On a subscribe/create retry path the same
// timeout usually IS deploy churn (a slow JetStream API during an upgrade),
// but this predicate cannot see which path it is on — callers that retry
// subscription setup must classify timeouts themselves.
func IsTransientFetchErr(err error) bool {
	if err == nil {
		return false
	}
	for _, target := range transientFetchErrs {
		if errors.Is(err, target) {
			return true
		}
	}
	return false
}

// IsTransientSubscribeErr reports whether a subscribe/create retry error is a
// recoverable interruption. It is a superset of [IsTransientFetchErr]: a
// retried subscribe also absorbs the stream not existing yet (rollout
// ordering, where the consumer comes up before the service that ensures the
// stream) and a JetStream API slow to answer the consumer-info/create request
// (nats.ErrTimeout / context.DeadlineExceeded — deploy churn on this path,
// unlike a fetch, where a timeout is an idle poll and a deadline can be a
// wedged server).
//
// Keeping the set here rather than in each caller is the point: two services
// already share these consumer loops, and the alert noise this package exists
// to remove comes back the moment their classifications drift.
func IsTransientSubscribeErr(err error) bool {
	return IsTransientFetchErr(err) ||
		errors.Is(err, nats.ErrStreamNotFound) ||
		errors.Is(err, nats.ErrTimeout) ||
		errors.Is(err, context.DeadlineExceeded)
}

// IsShutdownFetchErr reports whether a pull-consumer Fetch error is the benign
// result of our own teardown: the connection was closed or drained underneath
// the caller, with ctx already done. Those two errors are self-inflicted — the
// shutdown path drains the connection on purpose — so exiting without a log is
// honest.
//
// It is intentionally narrower than [IsTransientFetchErr]. The other
// interruptions can coincide with shutdown while meaning something real: a
// fetch that dies with ErrConsumerDeleted during a rolling deploy is the only
// evidence somebody deleted the durable, and swallowing it because ctx
// happened to be done leaves the redelivery storm after restart unexplained.
// Callers should log those (IsTransientFetchErr picks the severity) rather
// than exit silently.
//
// Use it to gate the error log in a fetch loop:
//
//	msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
//	if err != nil {
//		switch {
//		case errors.Is(err, nats.ErrTimeout):   // idle poll; keep fetching
//		case nuts.IsShutdownFetchErr(ctx, err): // our teardown; exit quietly
//		default:                                // log it; IsTransientFetchErr picks the severity
//		}
//	}
func IsShutdownFetchErr(ctx context.Context, err error) bool {
	return ctx.Err() != nil &&
		(errors.Is(err, nats.ErrConnectionClosed) || errors.Is(err, nats.ErrConnectionDraining))
}

// Drain drains nc and waits (bounded by timeout) for it to flush pending
// acks/publishes and reach CLOSED. nats.go's Conn.Drain is asynchronous — it
// starts the drain on a background goroutine and returns immediately — so a
// bare Drain in a shutdown cleanup would let the process exit before the flush
// completes. This subscribes to the connection's CLOSED status event, starts
// the drain, and blocks until the connection closes or timeout elapses. name
// labels the connection in the logs so a wedged drain can be attributed, and
// diagnostics are written to logger (defaulting to [slog.Default] when nil).
// ctx supplies log context only: shutdown callers commonly pass an already
// cancelled process context, so timeout remains the authoritative drain
// budget and preserves the opportunity to flush during teardown.
//
// timeout is the TOTAL time-to-CLOSED backstop, not the subscription-drain
// budget. The connect-time nats.DrainTimeout option caps only the
// subscription-drain phase; nats.go then runs an unconditional 5s publish flush
// before closing, so the true time-to-CLOSED is up to that flush longer than
// nats.DrainTimeout. timeout must exceed the connection's nats.DrainTimeout by
// at least the publish-flush budget or it will fire mid-drain and drop pending
// acks — [ShutdownGroup] sizes it automatically. timeout bounds how long we
// block; it is not a guarantee the drain finished. Once the consumer loops have
// joined (see [ShutdownGroup]) there is nothing left to drain, so on a reachable
// server this returns in milliseconds; the backstop only bites when the server
// is unreachable.
//
// Unlike a raw nc.Drain, this does not touch the connection's ClosedHandler, so
// a handler installed by [Connect] or by the caller (via [WithNATSOptions]) is
// preserved, and concurrent Drain calls on the same connection do not clobber
// one another.
//
// Drain is a no-op on a nil or already-closed connection. It returns nil only
// after the connection reaches CLOSED; immediate drain failures and timeouts
// are returned after force-closing the connection.
func Drain(ctx context.Context, nc *nats.Conn, name string, logger *slog.Logger, timeout time.Duration) error {
	if logger == nil {
		logger = slog.Default()
	}
	if nc == nil || nc.IsClosed() {
		return nil
	}

	// Register for the CLOSED transition before starting the drain so it cannot
	// be missed, and via a status listener rather than SetClosedHandler so we
	// never displace a handler the connection already has.
	closed := nc.StatusChanged(nats.CLOSED)
	defer nc.RemoveStatusListener(closed)

	if err := nc.Drain(); err != nil {
		// The connection can close after the IsClosed check above but before
		// Drain takes its lock. That is the same clean no-op as entering this
		// function with an already-closed connection, not a shutdown failure.
		if errors.Is(err, nats.ErrConnectionClosed) {
			return nil
		}
		logger.WarnContext(ctx, "nuts: NATS drain failed; closing",
			slog.String("conn", name), slog.Any("error", err))
		nc.Close()
		return fmt.Errorf("nuts: drain %s: %w", name, err)
	}

	if !waitTimedOut(closed, timeout) {
		logger.InfoContext(ctx, "nuts: NATS drained", slog.String("conn", name))
		return nil
	}

	logger.WarnContext(ctx, "nuts: NATS drain timed out before close", slog.String("conn", name))
	nc.Close()
	return fmt.Errorf("%w: %s after %s", ErrDrainTimeout, name, timeout)
}
// Package nuts provides shared NATS connection-lifecycle helpers for Entire
// services: a rotation-aware mTLS [Connect] with the org-standard resiliency
// options, a [Drain] that waits for a connection to flush and close on graceful
// shutdown, an [IsShutdownFetchErr] classifier so pull-consumer loops can treat
// a drain/close during shutdown as a clean exit rather than an error, and a
// [ShutdownGroup] that cancels background loops, joins them, and only then
// drains the connections — the ordering that keeps a Drain from racing an
// in-flight Fetch (COR-923).
//
// This root package is the connection-lifecycle core extracted from
// entire-core (entiredb), entire-api, and mirror-pipeline, which had each
// grown their own copy of this plumbing (COR-925). It depends only on nats.go.
//
// The subpackages carry the message-layer pieces those services shared
// (COR-929, deepened in COR-984) — [natsmsg] (trace-context propagation over
// message headers, the bounded deduped Publisher with a caller-selected
// Operation span name, the KeepInProgress AckWait heartbeat, the DeadLetter
// dead-letter capture, and the natsmsgtest.FakeMsg test double),
// [jsconsumer] (the durable JetStream pull-consumer scaffold, one-shot via Start
// or supervised via Run, plus Retry — the consumer's single retry mechanism —
// Schedule, the pure validator for a consumer's retry timing that fleet CI and
// the library share, and FloorMonitor, the ack-floor stall telemetry that can
// also arm Retry's experimental circuit breaker, ENT-1535), and [backoff] (the
// NakWithDelay redelivery policy —
// flat or growing — with Term-on-final-delivery, COR-762). The legacy
// nats.JetStreamContext publishing bridges were transitional and were removed
// once the last caller migrated (COR-1004). natsmsg and
// jsconsumer additionally depend on the OpenTelemetry API, and all three on
// nats.go's jetstream package; importing only the root package links none of
// that.
//
// [natsmsg]: https://pkg.go.dev/github.com/entireio/go-nuts/natsmsg
// [jsconsumer]: https://pkg.go.dev/github.com/entireio/go-nuts/jsconsumer
// [backoff]: https://pkg.go.dev/github.com/entireio/go-nuts/backoff
package nuts

// was failing alongside the blocker rather than being it (bounded to one per
// stall window, and the copy is replayable — see [Retry]). Use the monitor
// alone and it is just the health signal, leaving the quarantine decision to
// the adopter.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// DefaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	DefaultAckWait = 30 * time.Second
	// DefaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	DefaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → DefaultAckWait (see EffectiveAckWait)
	MaxDeliver     int           // 0 → DefaultMaxDeliver (see EffectiveMaxDeliver)
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// InactiveThreshold mirrors jetstream.ConsumerConfig.InactiveThreshold:
	// how long the durable may go without an active subscription before the
	// server deletes it; zero means never (the JetStream default for
	// durables) UNLESS the stream sets ConsumerLimits.InactiveThreshold — see
	// the note below. Consumers on interest-retention streams set this so a
	// decommissioned durable stops pinning every message it would have
	// received, instead of holding them until the stream's MaxAge.
	InactiveThreshold time.Duration

	// MaxAckPending mirrors jetstream.ConsumerConfig.MaxAckPending: the
	// server-side cap on deliveries outstanding un-acked across ALL replicas
	// sharing the durable; zero uses the server default (1000), or the stream's
	// ConsumerLimits.MaxAckPending when it sets one — see the note below.
	// Distinct from MaxMessages below, which caps only this process's
	// client-side buffer.
	//
	// # Stream ConsumerLimits fill in both zeros
	//
	// A stream may carry ConsumerLimits, and the server applies them to any
	// consumer that left the matching field zero. So on such a stream neither
	// zero above means what it says: this scaffold's consumers inherit the
	// STREAM's MaxAckPending instead of 1000, and — the consequential one — an
	// InactiveThreshold instead of never, which gives the durable a deletion
	// timer nobody here asked for. A durable deleted that way is recreated from
	// the stream's DeliverPolicy (all, by default) and replays the retained
	// backlog, so the cost of the surprise is a replay, not just a gap.
	//
	// Set both explicitly on a stream with ConsumerLimits, and read the
	// durable's STORED config rather than assuming either field above is what is
	// running. Requests that leave them unset are also what pedantic-mode
	// clients reject outright (NACK's controller drives fleet Consumer CRs that
	// way), so a config this scaffold applies quietly can fail to reconcile in
	// the cluster. Measured in internal/brokersemantics
	// (TestStreamConsumerLimitsAreInheritedBySilentConsumers).
	MaxAckPending int

	// BackOff mirrors jetstream.ConsumerConfig.BackOff: the redelivery
	// ladder, one delay per redelivery, applied in place of AckWait. The
	// server owns redelivery — this is the one schedule, and [Retry] defers to
	// it by leaving a failed delivery untouched rather than running a
	// competing one client-side. JetStream
	// repeats the last rung once the array runs out, so a short list under a
	// larger MaxDeliver is not a short ladder.
	//
	// Setting it alongside Retry is the intended combination. Its coherence —
	// total time to the dead-letter branch, agreement with AckWait, rung count
	// against MaxDeliver — is checked at Start through [Schedule], the same
	// function fleet CI runs over a rendered NACK Consumer CR.
	//
	// Leaving it nil is a choice, not a default: the broker still redelivers,
	// on AckWait, so the effective ladder becomes AckWait repeated up to
	// MaxDeliver. [Schedule] models it that way and holds it to the same
	// bounds, which is usually how an unset BackOff gets caught — an AckWait
	// sized for one RPC makes a fast, tight retry loop, and one sized for a
	// slow handler makes a very long one.
	//
	// Start always sends this value to CreateOrUpdateConsumer, so a nil also
	// CLEARS any ladder already on the durable. A consumer whose ladder is
	// managed declaratively therefore cannot just omit it here — that erases
	// the managed ladder on every start. Declarative management needs a
	// bind-only mode that skips consumer creation, which does not exist yet;
	// until it does, the app states the ladder here.
	BackOff []time.Duration

	// Retry is where this consumer's retries END: dead-letter capture, then
	// settle, plus — when its RetryConfig names a FloorMonitor — the
	// experimental floor-age circuit breaker. It does NOT schedule
	// redelivery; BackOff above does. When set, [Process] dead-letters an
	// undecodable payload instead of Terming it, and the whole schedule
	// (ladder, AckWait, MaxDeliver, and this Retry's expectations of them) is
	// validated together at Start. Its MaxDeliver must equal
	// EffectiveMaxDeliver().
	//
	// Handlers reach it through the closure they build, and call
	// [Retry.Settle] as their one disposition for a failed delivery. Nil
	// leaves disposition entirely to the handler, as before.
	Retry *Retry

	// FloorMonitor runs the durable's ack-floor health signal: [Start] polls
	// it and [Runner.Stop] joins that poll. Set it to publish the stall as a
	// gauge, or to drive a quarantine rule of your own, without adopting the
	// library's automatic breaker.
	//
	// Leave it nil when Retry already carries the monitor — Start uses that
	// one. Naming two different monitors is a Start error: one durable has one
	// ack floor, and one poll loop should read it.
	FloorMonitor *FloorMonitor

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	//
	// Setting this forces the prefetch to one message (see MaxMessages): the
	// heartbeat extends only the delivery the handler holds, so anything
	// buffered behind a long handler would exhaust its AckWait unextended.
	KeepInProgress bool

	// MaxMessages caps how many deliveries the consume loop buffers
	// client-side (jetstream.PullMaxMessages); 0 uses the nats.go default
	// (500). AckWait runs from server delivery into that buffer, not from
	// callback dispatch, and callbacks run serially — so a consumer whose
	// handler can approach AckWait should keep this small or queued
	// deliveries expire and redeliver concurrently to other replicas.
	// KeepInProgress forces it to 1; setting both to conflicting values is a
	// Start error.
	MaxMessages int
}

// EffectiveAckWait is the AckWait actually applied to the JetStream consumer:
// Config.AckWait, or DefaultAckWait when zero. Use it — not the raw field —
// anywhere the real value matters, e.g. wiring a natsmsg.KeepInProgress
// heartbeat by hand (a zero ackWait there is a no-op).
func (c Config) EffectiveAckWait() time.Duration {
	if c.AckWait == 0 {
		return DefaultAckWait
	}
	return c.AckWait
}

// EffectiveMaxDeliver is the MaxDeliver actually applied to the JetStream
// consumer: Config.MaxDeliver, or DefaultMaxDeliver when zero. Use it — not
// the raw field — when building a backoff.Policy for this consumer's
// messages: the two packages read zero differently (here it means "default
// to DefaultMaxDeliver"; on the policy it means unlimited redeliveries, the
// jetstream.ConsumerConfig semantics), so passing a zero Config.MaxDeliver
// through verbatim would make TermOnExhaustion never fire on the broker's
// real final delivery and orphan work-queue messages (COR-762).
func (c Config) EffectiveMaxDeliver() int {
	if c.MaxDeliver == 0 {
		return DefaultMaxDeliver
	}
	return c.MaxDeliver
}

// validate rejects the configuration errors no retry can fix; shared by
// [Start] (one-shot) and [Run] (supervised, which must fail fast on these
// rather than retry them forever).
func (c Config) validate(nc *nats.Conn, onMsg func(jetstream.Msg)) error {
	if c.KeepInProgress && c.MaxMessages > 1 {
		return fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", c.Name, c.MaxMessages)
	}
	if c.Stream == "" {
		return fmt.Errorf("jsconsumer(%s): Stream is required", c.Name)
	}
	if c.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return fmt.Errorf("jsconsumer(%s): Durable is required", c.Name)
	}
	if onMsg == nil {
		return fmt.Errorf("jsconsumer(%s): onMsg is required", c.Name)
	}
	if c.FilterSubject != "" && len(c.FilterSubjects) != 0 {
		return fmt.Errorf("jsconsumer(%s): set FilterSubject or FilterSubjects, not both", c.Name)
	}
	for i, subject := range c.FilterSubjects {
		if subject == "" {
			return fmt.Errorf("jsconsumer(%s): FilterSubjects[%d] is empty", c.Name, i)
		}
	}
	if c.AckWait < 0 {
		return fmt.Errorf("jsconsumer(%s): AckWait must not be negative", c.Name)
	}
	if c.MaxDeliver < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxDeliver must be -1 (unlimited), 0 (default), or positive", c.Name)
	}
	if c.MaxMessages < 0 {
		return fmt.Errorf("jsconsumer(%s): MaxMessages must not be negative", c.Name)
	}
	if c.MaxAckPending < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxAckPending must be -1 (unlimited), 0 (server or stream ConsumerLimits default), or positive", c.Name)
	}
	if c.InactiveThreshold < 0 {
		return fmt.Errorf("jsconsumer(%s): InactiveThreshold must not be negative", c.Name)
	}
	if c.FloorMonitor != nil && c.Retry != nil && c.Retry.Monitor() != nil && c.FloorMonitor != c.Retry.Monitor() {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, errMonitorConflict)
	}
	if c.Retry != nil && c.Retry.MaxDeliver() != c.EffectiveMaxDeliver() {
		// A policy that disagrees with the broker either never reaches its
		// terminal branch or reaches it early (COR-762) — and with Retry the
		// terminal branch is the DLQ capture, so the disagreement is a lost
		// message rather than a late one.
		return fmt.Errorf("jsconsumer(%s): Retry MaxDeliver is %d but the consumer's is %d: they must match or the dead-letter branch misses the broker's final delivery", c.Name, c.Retry.MaxDeliver(), c.EffectiveMaxDeliver())
	}
	// The whole retry schedule — the server's ladder plus whatever the Retry
	// expects of it — is checked in one place, by the same function fleet CI
	// runs over a rendered Consumer CR and a future bind-only mode will run
	// against the durable's live config. See [Schedule].
	//
	// Only for a consumer that opted into one of them. A durable that carries
	// neither a Retry nor a ladder has nothing here to be coherent about, and
	// must not acquire a new way to fail at startup because this package grew
	// a validator. It runs AFTER the cross-check above so a genuine
	// MaxDeliver mismatch reports as itself rather than as generic
	// incoherence.
	if c.Retry != nil || len(c.BackOff) > 0 {
		if err := c.schedule().Err(); err != nil {
			return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
		}
	}
	if nc == nil {
		return fmt.Errorf("jsconsumer(%s): nil nats conn", c.Name)
	}
	return nil
}

// floorMonitor is the single monitor this consumer polls: the one named on
// the Config, or the one its Retry carries. validate has already rejected two
// different ones.
func (c Config) floorMonitor() *FloorMonitor {
	if c.FloorMonitor != nil {
		return c.FloorMonitor
	}
	if c.Retry != nil {
		return c.Retry.Monitor()
	}
	return nil
}

// schedule is this consumer's retry timing as plain values: the server ladder
// it runs, and the client-side expectations its Retry holds about that ladder.
func (c Config) schedule() Schedule {
	s := Schedule{
		ServerBackOff: c.BackOff,
		MaxDeliver:    max(c.EffectiveMaxDeliver(), 0), // unlimited reads as "no terminal branch"
		AckWait:       c.EffectiveAckWait(),
	}
	if c.Retry != nil {
		exp := c.Retry.expectations()
		s.CaptureReserve, s.MaxTimeToDeadLetter = exp.CaptureReserve, exp.MaxTimeToDeadLetter
		s.RecoverBy, s.FloorAge = exp.RecoverBy, exp.FloorAge
	}
	return s
}

// checkAgainstStream re-runs the schedule check with the stream's retention
// filled in, which [Config.validate] cannot know: a ladder that outlives
// max_age never reaches its own dead-letter branch, because the stream
// discards the message first. That is silent data loss dressed as a retry
// policy, and it is only visible with both halves in hand.
//
// A stream this cannot read is an error, not a pass. That distinction is the
// whole value of the check: it exists to stop a consumer whose ladder outlives
// retention from starting, so answering "fine" whenever the retention is
// unknown removes the protection in exactly the case where nothing else
// supplies it. Reading the stream and creating the consumer are separate
// JetStream API subjects ($JS.API.STREAM.INFO.> and $JS.API.CONSUMER.>), so a
// credential can be able to do the second and not the first — and then a
// swallowed error means the invalid ladder starts and the source expires the
// message before capture, which is the ENT-1492 loss this check promises to
// prevent.
//
// The legitimate case still rides out, but through the classifier rather than
// through a blanket pass: a stream that does not exist yet — the
// declarative-provisioning race — surfaces as [jetstream.ErrStreamNotFound],
// which [isRetryableStartError] already treats as retryable, so [Run] keeps
// waiting for the stream to appear exactly as before. A denied
// STREAM.INFO publish gets no reply and times out, which is retryable too: the
// consumer never starts, [Run] logs the failure on every attempt, and the safe
// outcome is a consumer that is loudly absent rather than quietly unchecked.
func (c Config) checkAgainstStream(ctx context.Context, js jetstream.JetStream) error {
	if c.Retry == nil && len(c.BackOff) == 0 {
		return nil
	}
	// js.Stream fetches STREAM.INFO to build the handle, so the config is
	// already in hand — a second Info call would be one more round trip and one
	// more failure mode on the startup path.
	stream, err := js.Stream(ctx, c.Stream)
	if err != nil {
		return fmt.Errorf("jsconsumer(%s): read stream %q to check the ladder against its retention: %w", c.Name, c.Stream, err)
	}
	info := stream.CachedInfo()
	if info == nil {
		return fmt.Errorf("jsconsumer(%s): stream %q returned no config to check the ladder against its retention", c.Name, c.Stream)
	}
	sched := c.schedule()
	sched.StreamMaxAge = info.Config.MaxAge
	if err := sched.Err(); err != nil {
		return fmt.Errorf("jsconsumer(%s): %w", c.Name, err)
	}
	return nil
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

// isShutdownConsumeErr reports whether a consume error is the benign result
// of the connection going away during shutdown. [nuts.IsShutdownFetchErr]
// covers the core nats.go sentinels, but the jetstream consume loop surfaces
// its OWN [jetstream.ErrConnectionClosed] — a distinct value that wraps
// neither — so it must be matched separately or a clean rollout drain still
// logs a warning (the COR-923 noise this suppression exists to remove). As
// with the root classifier, it is only "clean" when ctx is already done; a
// mid-run connection loss is a genuine fault worth logging.

// dispatch call it ever made has already returned (and therefore already
// called wg.Add), so this Wait can never race a late Add.
//
// ENT-1703: jsconsumer.Run above is always given ctx unmodified — the pull
// loop must still stop accepting new deliveries the instant ctx is canceled
// (SIGTERM), exactly as before. But every dispatched handler in this durable
// now runs on drainCtx (see the next paragraph for why it is ONE context
// shared by the whole durable, not one per message): detached from ctx's
// immediate cancellation (context.WithoutCancel) and force-canceled, ONCE,
// c.drainGrace after ctx itself is done. This is the fix for the gap ENT-1696
// deliberately left alone: that change made the
// hard-fail recovery path (deadLetterFailingRun/recoverHandlerPanic/
// nakSnapshotBackoffOrFail) fast and clean, but every in-flight handler still
// shared ctx directly, so a rolling deploy (this repo redeploys the runner on
// every merge to main, roughly every 15-40 minutes — gh run list --repo
// entirehq/entire-api --workflow deploy.yml over recent history) aborted work
// that might have been seconds from succeeding. Giving it a bounded grace
// window instead lets it finish naturally most of the time, falling back to
// that same (now-fast) hard-fail path only once the window elapses. A
// cancellation-interrupted provision is retryable ONLY where the adapter's
// cleanup CONFIRMS the sandbox was torn down (sandbox.ProvisionFailure,
// internal/sandbox/daytona/provision.go) — nothing leaked, so a surviving pod
// may re-provision on the next redelivery; releaseProvisionClaim (handlers.go)
// detaches its claim-release write from this cancellation so that retry can
// actually fire (ENT-1707). A cancellation with UNCONFIRMED cleanup stays an
// ambiguous, unretryable failure and terminalizes, unchanged.
//
// The window is anchored to ctx being canceled, not to when any individual
// message is dispatched — deliberately a SINGLE shared context/timer for the
// whole durable, not one per dispatched message. MaxMessages is
// c.concurrency*2 (durableConfig above), so under load the broker can already
// be holding up to c.concurrency MORE deliveries than can run, each blocked on
// `sem <- struct{}{}` below; if each got its own fresh c.drainGrace window
// starting when ITS goroutine finally ran, a message dispatched only after
// shutdown began — the opposite of "stop accepting new work immediately" —
// would get a full new grace period, and runDurable's overall return would
// scale with how many messages were queued, not with drainGrace itself. Under
// the shared drainCtx, a handler dispatched after the window has already
// elapsed simply receives an already-canceled context and fails immediately —
// correct, since accepting brand-new work during drain was never the goal.
// See defaultDrainGrace's doc for the shutdown-time budget this window is
// sized against.
//
// The dispatched goroutine recovers a panic from handle rather than letting
// it crash the pod: C.1.2 drops real provider SDK/network calls into these
// handlers, and a deterministic panic (a bad response shape, a nil the SDK
// hands back) would otherwise crash-loop the pod on every redelivery of the
// SAME poison message. A recovered panic is treated exactly like a decode
// failure — dead-lettered (reason ReasonPanic) then Ack'd off the WorkQueue —
// rather than re-panicking or a bare Nak (which would just crash-loop via
// AckWait-driven redelivery instead of process-driven redelivery, no better).
// This deliberately diverges from internal/ingest/jobs.go's JobsConsumer,
// which has no recover: index-job handlers only touch entiredb/Postgres
// through this codebase's own clients, a much narrower failure surface than
// an external sandbox provider's SDK.
func (c *Consumer) runDurable(ctx context.Context, cfg jsconsumer.Config, handle func(context.Context, jetstream.Msg)) error {
	// Resolved ONCE per durable (not per message): cfg is fixed for the whole
	// call, so which of the two backoff policies applies never changes across
	// the durable's lifetime. See backoffPolicyForConfig's doc.
	policy := c.backoffPolicyForConfig(cfg)

	// drainCtx: see runDurable's doc above (why this is shared per-durable).
	drainCtx, cancelDrain := context.WithCancel(context.WithoutCancel(ctx))
	defer cancelDrain()
	go func() {
		select {
		case <-ctx.Done():
			t := time.NewTimer(c.drainGrace)
			defer t.Stop()
			select {
			case <-t.C:
				logCtx := context.WithoutCancel(ctx)
				slog.WarnContext(logCtx, "runner: drain grace elapsed; force-canceling in-flight handlers",
					slog.String("durable", cfg.Durable), slog.Duration("drain_grace", c.drainGrace))
				c.metrics.drainGraceExpired.Add(logCtx, 1, attr("durable", cfg.Durable))
			case <-drainCtx.Done(): // every handler already returned on its own
			}
			cancelDrain()
		case <-drainCtx.Done(): // runDurable returning without ctx ever canceling
		}
	}()

	pool := newWorkerPool(c.concurrency)
	stopWorkerGauges := c.observeWorkerPool(cfg.Durable, pool)
	defer stopWorkerGauges()
	var wg sync.WaitGroup
	dispatch := func(msg jetstream.Msg) {
		wg.Add(1)
		pool.acquire() // blocks → backpressure
		go func() {
			defer wg.Done()
			defer pool.release()
			// capture lets decodeAndDispatch record the decoded run id
			// where recoverHandlerPanic (below, same goroutine) can read it
			// after a panic — see panicRunIDCapture's doc.
			capture := &panicRunIDCapture{}
			dctx := withPanicRunIDCapture(drainCtx, capture)
			// withDurableBackoffPolicy lets nakBackoff/deadLetter (below) pick
			// the RIGHT policy for whichever durable actually delivered msg —
			// see durableBackoffPolicyFromContext's own doc for why this is a
			// context value rather than a parameter threaded through every
			// one of handlers.go's dozen-plus deadLetter/deadLetterFailingRun
			// call sites.
			dctx = withDurableBackoffPolicy(dctx, policy)
			defer c.recoverHandlerPanic(dctx, msg, capture)
			handle(dctx, msg)
		}()
	}
	err := jsconsumer.Run(ctx, c.nc, cfg, dispatch)
	wg.Wait()
	return err
}

// backoffPolicyForConfig selects Consumer.workBackoffPolicy/pollBackoffPolicy
// by cfg's own effective MaxDeliver — cfg.EffectiveMaxDeliver() (never the
// raw field, per go-nuts/jsconsumer's own documented bridge: a zero
// Config.MaxDeliver means "use jsconsumer's DefaultMaxDeliver" there, but
// "unlimited" to backoff.Policy, so passing the raw field through would
// silently misclassify an unset MaxDeliver as the poll durable's unbounded
// policy). This package's own workConfig/pollConfig always set MaxDeliver
// explicitly (workMaxDeliver/pollMaxDeliver), so in practice this is just
// import daytona just to boot). Deliberately kept equal to
// daytona.DefaultBaseSnapshot's value; TestDefaultBaseSnapshotMatchesDaytonaAdapterDefault
// (a test-only cross-package check — production code never imports daytona)
// fails loudly if the two ever drift instead of silently rotting.
const defaultBaseSnapshot = "daytonaio/sandbox:0.9.0"

