// Outcome is what [Retry.Settle] did with a failed delivery.
type Outcome string

const (
	// OutcomeRetried means the delivery was left for the server to redeliver
	// on its ladder — see [Retry.awaitRedelivery], where doing nothing IS the
	// disposition.
	OutcomeRetried Outcome = "retried"
	// OutcomeDeadLettered means the raw message and its headers were captured
	// to the DLQ subject and the original Acked, releasing the ack floor.
	OutcomeDeadLettered Outcome = "dead_lettered"
	// OutcomeStranded means the capture failed with no deliveries left to
	// retry it: the delivery cap is reached, so the broker will not redeliver
	// and nothing in the system will touch this message again. It is unsettled, it is pinning the
	// ack floor, and it needs an operator — the non-lossy break-glass in
	// runbooks/nats-poison-ref-event.md. Alert on this; it is the one outcome
	// no automation clears.
	//
	// Nothing reached the DLQ, so the stream copy is the only one left. That
	// is what separates it from [OutcomeUncertain].
	OutcomeStranded Outcome = "stranded"
	// OutcomeUncertain means the message reached the DLQ but the
	// acknowledgement that would release it could not be confirmed, on a
	// delivery with none left behind it. The data is safe; what is unknown is
	// whether the original settled.
	//
	// It is deliberately not reported as stranded, because a synchronous ack
	// failure does not prove the ack failed: DoubleAck waits for the server's
	// confirmation, and a lost or timed-out confirmation is indistinguishable
	// from one the server never sent. The message may be settled and gone.
	//
	// That distinction is operational, not cosmetic. A responder who reads
	// "stranded" reaches for the break-glass removal, and removing a stream
	// message this consumer has in fact acked takes it away from every OTHER
	// consumer of that stream.
	//
	// So on Uncertain, CHECK before acting — but read the check correctly, because
	// only one direction of it proves anything:
	//
	//   - The floor has advanced PAST this sequence: the ack landed. Nothing to
	//     do. This direction is sound.
	//   - The floor has NOT advanced: this proves nothing about THIS message.
	//     AckFloor is a contiguous watermark, so any older unacked message pins
	//     it no matter what happened to this one — see
	//     TestAckFloorStaysStationaryWhileLaterMessagesAck in
	//     internal/brokersemantics. Treating non-advancement as stranding is how
	//     a responder gets talked into removing an already-settled message.
	//
	// To implicate this message specifically, the floor has to be pinned AT it —
	// this sequence is the oldest unacked one — rather than merely below it
	// because something older has not settled. Until that is established the
	// state stays uncertain, and uncertain is not a licence to remove: the
	// payload is already safe in the DLQ, so the cost of waiting is a pinned
	// floor, while the cost of guessing wrong is data loss for every other
	// consumer of the stream. Note also that NumAckPending cannot substitute for
	// the check — an exhausted message pins the floor with NumAckPending at zero
	// (TestExhaustedDeliveryPinsFloorWithNoAckPending).
	OutcomeUncertain Outcome = "uncertain"
)

// Cause explains an [OutcomeDeadLettered] settlement; it is empty on a retry.
type Cause string

const (
	// CauseFloorAge is the circuit breaker: this message was pinning the
	// durable's ack floor and the floor had been stalled past FloorAge.
	CauseFloorAge Cause = "floor_age"
	// CauseExhausted is the ordinary terminal branch: the delivery cap was
	// reached (ENT-1492's dead-letter-then-Ack, replacing a bare Term).
	CauseExhausted Cause = "max_deliver"
	// CausePermanent is a caller-declared unprocessable message, dead-lettered
	// by [Retry.DeadLetter] without consuming the ladder.
	CausePermanent Cause = "permanent"
)

// Settlement reports what [Retry.Settle] chose and the state it chose it
// from, for the caller's metrics and log lines. FloorAge and Floor are zero
// when no ack-floor observation was available (the breaker is disabled, or
// [Start] has not run yet).
type Settlement struct {
	Outcome   Outcome
	Cause     Cause
	Delivered int           // this message's delivery count, 1-based
	Floor     uint64        // last observed ack floor (stream sequence)
	FloorAge  time.Duration // how long the floor had been stalled there
	// FailingFor is how long this message has been failing, MEASURED from the
	// first failure this process observed — the message-local half of the
	// breaker's condition. It is not inferred from the delivery count, which
	// JetStream also increments on AckWait expiry — which is the NORMAL
	// redelivery path here, not an anomaly (see Retry.noteFailure) — and
	// it restarts on process restart.
	FailingFor time.Duration
	// BreakerTripped reports that the quarantine condition was met for this
	// message, whether or not the breaker acted on it — so an adopter running
	// [BreakerObserve] can count what enforcing WOULD have dead-lettered.
	BreakerTripped bool
	// Captured reports that the raw message reached the DLQ. It is the field
	// that separates the two strandings: with Captured the data is safe and at
	// most the original needs clearing, without it nothing was preserved and the
	// stream copy is all that remains.
	//
	// "At most" is doing work there. Captured says nothing about whether the
	// original is still unsettled — see [OutcomeUncertain] for why a stationary
	// ack floor is not evidence that it is, and why removing on that basis takes
	// the message from every other consumer of the stream.
	Captured bool
}

// BreakerMode is whether a [Retry] acts on its [FloorMonitor]'s stall signal.
// ladderSpent reports whether the handler's share of the delivery budget is
// used up, so the next step is the DLQ. It stops CaptureReserve deliveries
// short of the broker's own cap, leaving those to retry a failed capture.
// A delivered count of 0 (no metadata) is never exhaustion — the safe default
// is another retry, matching backoff.IsFinalDelivery.
func (r *Retry) ladderSpent(delivered int) bool {
	return delivered > 0 && delivered >= r.cfg.MaxDeliver-r.cfg.CaptureReserve
}

// attach binds the host's log identity, when the RetryConfig left it unset.
// Called by [Start] on every attempt, including [Run]'s recreates.
// terminate runs the capture-then-settle sequence shared by [Settle]'s two
// terminal branches and [Retry.DeadLetter], and classifies every way it can
// fall short. s must already carry its Cause.
func (r *Retry) terminate(ctx context.Context, msg jetstream.Msg, s Settlement, reason string) (Settlement, error) {
	logger, name := r.log()
	spent := s.Delivered > 0 && s.Delivered >= r.cfg.MaxDeliver

	// Capture and settle on a context that shutdown cannot cancel. The module's
	// shutdown ordering cancels the loops' context, joins them, and only THEN
	// drains the connections (nuts.ShutdownGroup, COR-923) — so throughout the
	// join window this ctx is already done while the connection is still fully
	// usable. On the handler ctx a rollout landing on the FINAL delivery fails
	// the capture on ctx.Err() alone and reports OutcomeStranded: a strand
	// manufactured by timing, on a message that was perfectly capturable with
	// the broker right there. The same cancellation on the DoubleAck would
	// report OutcomeUncertain and point a responder at a message that only
	// needed one more round-trip.
	//
	// Detaching cancellation cannot hang the drain, because neither operation
	// was relying on ctx for its bound: the capture publish and the DoubleAck
	// each apply their own (dlqPublishTimeout, dlqAckTimeout). WithoutCancel
	// drops the parent's deadline along with its cancellation, which is why
	// those explicit bounds are what matters. This narrows the window rather
	// than closing it absolutely — a terminate outlasting nuts.DefaultJoinTimeout
	// still has the connection drained under it — but it removes the case that
	// failed immediately and by construction.
	//
	// Values are preserved, so the span and trace context the handler was given
	// still carry into the capture.
	//
	// The WHOLE settle sequence runs detached, not just the capture:
	// natsmsg.DeadLetter detaches its own publish too (COR-1487), but this is what
	// covers the DoubleAck below, which nothing else does.
	settleCtx := context.WithoutCancel(ctx)

	if err := r.capture(settleCtx, msg, s.Cause, reason); err != nil {
		if spent {
			// Out of deliveries: no redelivery follows, so saying "retried"
			// would be a lie. Leave it unsettled and name the state.
			s.Outcome = OutcomeStranded
			logger.ErrorContext(ctx, name+": message stranded; dead-letter capture failed with no deliveries left",
				slog.Any("error", err),
				slog.String("cause", string(s.Cause)),
				slog.String("reason", reason),
				slog.Int("delivered", s.Delivered),
				slog.Uint64("ack_floor", s.Floor))
			r.observe(ctx, msg, s)
			return s, fmt.Errorf("settle:stranded: %w", err)
		}
		// Deliveries remain — leave it to the ladder so the capture is retried
		// on the next delivery. Preserve the cause: the terminal branch was
		// reached and could not complete.
		waiting := r.awaitRedelivery(ctx, msg, s)
		waiting.Cause = s.Cause
		return waiting, err
	}
	s.Captured = true

	// DoubleAck, not Ack: a plain Ack is fire-and-forget, so a lost one leaves
	// the floor pinned with nothing reporting it. Waiting for the server's
	// confirmation is what makes the settlement a fact rather than a hope, and
	// it costs one round-trip on a path that only runs when a message is being
	// given up on.
	ackCtx, cancel := context.WithTimeout(settleCtx, dlqAckTimeout)
	defer cancel()
	if err := msg.DoubleAck(ackCtx); err != nil {
		if spent {
			// The copy is safe in the DLQ; whether the ORIGINAL settled is
			// unknown. A failed DoubleAck means the confirmation did not come
			// back, which is not the same as the ack not landing — so this is
			// reported as uncertain rather than stranded, and the log says
			// what to check. See [OutcomeUncertain] for why over-claiming
			// here is worse than useless: it points a responder at a
			// destructive remedy for a message that may already be settled.
			s.Outcome = OutcomeUncertain
			logger.ErrorContext(ctx, name+": settlement unconfirmed; captured to the DLQ but the ack was not acknowledged, with no deliveries left",
				slog.Any("error", err),
				slog.String("cause", string(s.Cause)),
				slog.Int("delivered", s.Delivered),
				slog.Uint64("ack_floor", s.Floor),
				slog.String("check", "has the ack floor advanced past this message? if so the ack landed and no action is needed. if not, that is NOT proof it is unsettled — an older unacked message pins the floor regardless; the copy is already safe in the DLQ, so do not remove the original until the floor is shown to be pinned AT this sequence"))
			r.observe(ctx, msg, s)
			return s, fmt.Errorf("settle:dlq_ack_unconfirmed: %w", err)
		}
		// A delivery remains: the message redelivers and is captured again.
		// A duplicate in the DLQ beats a pinned floor.
		s.Outcome = OutcomeRetried
		r.observe(ctx, msg, s)
		return s, fmt.Errorf("settle:dlq_ack_failed: %w", err)
	}

	s.Outcome = OutcomeDeadLettered
	r.forgetFailure(streamSeq(msg))
	logger.WarnContext(ctx, name+": dead-lettered",
		slog.String("cause", string(s.Cause)),
		slog.String("reason", reason),
		slog.Int("delivered", s.Delivered),
		slog.Duration("failing_for", s.FailingFor),
		slog.Uint64("ack_floor", s.Floor),
		slog.Duration("floor_stalled_for", s.FloorAge))
	r.observe(ctx, msg, s)
	return s, nil
}

